  Ep.blobs.push({x:Ep.x-170,z:Ep.z-140,R:110,H:55},{x:Ep.x+200,z:Ep.z+120,R:150,H:60});Ep.mal=pad(Ep,-170,-140,14);Ep.sanct=pad(Ep,20,0,90,0,4);
  for(let i=0;i<9;i++){const a=i/9*TAU;Ma.blobs.push({x:Ma.x+Math.cos(a)*Ma.R*1.15,z:Ma.z+Math.sin(a)*Ma.R*1.15,R:200,H:90+40*Math.sin(i*2.3)});}Ma.town=pad(Ma,0,0,160,0,4);
  Ol.blobs.push({x:Ol.x-40,z:Ol.z-230,R:120,H:60});Ol.altis=pad(Ol,0,-10,130,0,4);Ol.stad=pad(Ol,200,-60,110,0,4);Ol.ws=pad(Ol,-170,60,26,0,4);
  {const Mr=G('maraton');Mr.arrive=pad(Mr,-Mr.R*0.72,30,24,0,3);Mr.lake={x:Mr.x+110,z:Mr.z-250,rx:100,rz:70};
   Mr.blobs.push({x:Mr.x-130,z:Mr.z-480,R:300,H:160},{x:Mr.x-470,z:Mr.z+60,R:220,H:120},{x:Mr.x-300,z:Mr.z+380,R:200,H:90});
   Mr.soros=pad(Mr,30,30,24,0,3);Mr.plat=pad(Mr,-150,-70,16,0,3);Mr.trop=pad(Mr,70,-150,8,0,3);Mr.herak=pad(Mr,-240,140,20);Mr.town=pad(Mr,-200,-150,60,0,4);Mr.town.house=true;}
  {const T=G('termopilas');T.arrive=pad(T,-T.R*0.72,20,24,0,3);
   for(let i=0;i<6;i++)T.blobs.push({x:T.x-500+i*200,z:T.z-330-(i%2)*40,R:280,H:230+40*Math.sin(i*1.7)});
   T.anth=pad(T,-210,10,40,0,3);T.spring=pad(T,-70,0,18,0,2.5);T.wall=pad(T,70,5,30,0,3);T.kol=pad(T,120,-10,26,0,3);T.anop=pad(T,190,-40,10,0,3.5);T.town=pad(T,250,15,40,0,3);T.town.house=true;
   T.blobs.push({x:T.kol.x,z:T.kol.z,R:28,H:9});}
  for(const p of[Me.town,Co.town,Pl.town,Ar.town,Ma.town])p.house=true;   // en el centro de la ciudad sí puede haber casas
