// llegada: el arriero Lisicles también recorre estos caminos
function greekArrive(I,label){const a=I.arrive;arriero(I.id,a.x+3,a.z+3,-Math.PI/2);PORTS[I.id+(I.sea?'_n':'')]={x:a.x-4,z:a.z,yaw:-Math.PI/2,label};}
function buildGreece2(){
  const G=id=>ISLANDS.find(I=>I.id===id);
  // ------------------------------------------------ Mégara
  {const I=G('megara'),t=I.town;
   ringWall(t.x,t.z,190,[0,Math.PI/2,Math.PI,-Math.PI/2],lam('#b9a986'),7,7);
   {const f=I.fount;blockBuilding({name:'Fuente de Teágenes',x:f.x,z:f.z-4,rot:0,w:16,d:8,h:5.5,mat:M.limestone});for(let i=0;i<5;i++)addColumn(f.x-6+i*3,f.h,f.z+0.6,0.32,4.2,0,'doric');pool(f.x,f.z+4,14,4,f.h);
    place('fuente_teagenes','Fuente de Teágenes','ΚΡΗΝΗ ΘΕΑΓΕΝΟΥΣ','A finales del siglo VII, el tirano Teágenes hizo construir esta fuente, que Pausanias todavía admiraba por su tamaño, su decoración y el número de sus columnas. Teágenes fue el suegro de Cilón, el ateniense que intentó hacerse tirano de Atenas ocupando la Acrópolis, hacia el 632: sus partidarios fueron asesinados junto a los altares, y los Alcmeónidas cargaron desde entonces con la maldición.',f.x+12,f.z+6,0);}
   {const o=I.oly;temple({name:'Olimpieion de Mégara',x:o.x,z:o.z,rot:Math.PI/2,W:13,L:26,nW:6,nL:12,colD:1.1,colH:6.2,gy:o.h,cella:{w:8,l:15,door:2.6}});
    {// la estatua inacabada de Teocosmo: rostro de oro y marfil, el resto de arcilla y yeso; detrás del templo, los troncos a medio desbastar (Pausanias I 40.4)
     const sg=grp(o.x,o.h,o.z,Math.PI/2),clay=lam('#c9b8a0');box(3.4,1.2,2.6,clay,0,0.6,-4.2,sg);box(2.4,1.4,1.8,clay,0,1.9,-4.4,sg);
     const zs=makePerson({noVary:true,chiton:'#d8cdb8',himation:'#b9a588',beard:true,hair:'#d9b44a',beardC:'#d9b44a',skin:'#efe4cc',scale:1.9});zs.position.set(0,1.2,-4.2);zs.rotation.y=0;sg.add(zs);
     box(1.6,0.12,0.12,lam('#a8957a'),0.9,3.6,-3.6,sg);addCirc(...toW(0,-4.2,o.x,o.z,Math.PI/2),2);
     for(let k=0;k<4;k++){const lg=new THREE.Mesh(new THREE.CylinderGeometry(0.35,0.42,4.5,8),lam('#8a6a4a'));lg.rotation.z=Math.PI/2;lg.position.set(-2+k*1.3,0.4,17+k%2*0.6);sg.add(lg);}}
    place('olimpieion_megara','Olimpieion de Mégara','ΟΛΥΜΠΙΕΙΟΝ','El templo de Zeus Olímpico de Mégara. Dentro hay una estatua del dios que no se terminó: el escultor Teocosmo, con ayuda de Fidias, había hecho el rostro de oro y marfil, pero al estallar la guerra del Peloponeso los megarenses gastaron el dinero en la guerra, y el resto del cuerpo se quedó de arcilla y yeso. Detrás del templo aún se ven los bloques de madera que debían recubrirse.',o.x+18,o.z+6,0);}
   {const s=I.sch;stoa({name:'Pórtico de Euclides',x:s.x,z:s.z,rot:0,len:24,depth:7,colH:4.4,colD:0.55});NPC_POS.euclides_megara=[s.x,s.z+8,Math.PI];
    place('escuela_megara','La escuela de Mégara','ΜΕΓΑΡΙΚΟΙ','Aquí enseña Euclides de Mégara (no confundir con el matemático Euclides de Alejandría, que nacerá dentro de medio siglo), discípulo de Sócrates. Tras la muerte de Sócrates en el 399, Platón y otros discípulos se refugiaron unos días en su casa. Sus alumnos, los megáricos, son famosos por sus argumentos y sus paradojas.',s.x-16,s.z+8,0);}
   place('decreto_megara','El decreto megárico','ΨΗΦΙΣΜΑ','Hacia el 432, Atenas prohibió a los megarenses entrar en su Ágora y en los puertos de su imperio. Para una ciudad que vivía del comercio fue la ruina, y el decreto fue una de las causas de la guerra del Peloponeso. Aristófanes se burló del asunto en Los acarnienses: un megarense hambriento intenta vender a sus hijas disfrazadas de cerditos.',t.x-20,t.z+30,0);
   place('nisea','Nisea, el puerto de Mégara','ΝΙΣΑΙΑ','Mégara tiene su puerto en Nisea, en el golfo Sarónico, unida a la ciudad por dos muros largos de unos ocho estadios, como los de Atenas y el Pireo. Frente al puerto está el islote de Minoa. En la guerra del Peloponeso, el ateniense Nicias tomó Minoa en el 427 para vigilar el puerto, y en el 424 los atenienses entraron por sorpresa en los muros largos y se quedaron con Nisea, como cuenta Tucídides. Mégara pasó la guerra cercada entre Atenas y Corinto.',t.x+40,t.z-30,0);
   place('colonias_megara','Las colonias de Mégara','ΑΠΟΙΚΙΑΙ','Para ser una ciudad pequeña, Mégara fundó colonias muy lejos: Mégara Hiblea en Sicilia y, en los estrechos que llevan al mar Negro, Calcedonia y, unos años después, Bizancio. Heródoto cuenta que un general persa llamó «ciegos» a los de Calcedonia, porque habían escogido la orilla peor teniendo delante el mejor sitio, donde luego se fundó Bizancio. Aquí nació también el poeta Teognis, que escribió consejos en verso a su joven amigo Cirno.',t.x-46,t.z-10,0);
   destHouses(I,t.x,t.z,40,150,false);greekArrive(I,'Mégara');
   islandVillagers(I,t.x+10,t.z+20,5,['Los atenienses nos cerraron sus puertos y casi nos matan de hambre. Ahora vuelven a comprarnos la lana.','Aquí tejemos las mejores túnicas de trabajo de Grecia: media Atenas va vestida con lana de Mégara.','Euclides dice que el bien es uno solo, aunque lo llamemos sabiduría, dios o inteligencia. Yo prefiero el vino.','Teágenes hizo la fuente; nosotros solo la usamos. Algo es algo.']);}
  // ------------------------------------------------ Corinto
  {const I=G('corinto'),t=I.town;
   {const a=I.apollo;temple({name:'Templo de Apolo de Corinto',x:a.x,z:a.z,rot:Math.PI/2,W:21.5,L:53.8,nW:6,nL:15,colD:1.7,colH:7.2,gy:a.h,cella:{w:13,l:34,door:3,antis:4,antisCols:true}});
    place('apolo_corinto','Templo de Apolo','ΝΑΟΣ ΑΠΟΛΛΩΝΟΣ','Uno de los templos de piedra más antiguos de Grecia, de hacia el 540 a.C.: seis por quince columnas dóricas, robustas, y cada fuste es un solo bloque de piedra caliza, sin tambores. Desde aquí se ve el golfo de Corinto. Siete de sus columnas seguirán en pie veinticuatro siglos después.',a.x+30,a.z+8,0);}
   {const c=I.acro;temple({name:'Templo de Afrodita',x:c.x,z:c.z,rot:Math.PI/2,W:8,L:14,nW:4,prostyle:true,colD:0.6,colH:4.4,gy:c.h,cella:{w:7,l:8,door:2.2}});ringWall(c.x,c.z,60,[Math.PI/2],lam('#b5a37e'),6,0);
    place('acrocorinto','Acrocorinto','ΑΚΡΟΚΟΡΙΝΘΟΣ','La montaña que hace de acrópolis de Corinto, de casi seiscientos metros: desde arriba se ven los dos mares. En lo alto, un templo de Afrodita y una fuente, la Pirene alta. Según el mito, aquí Belerofonte domó a Pegaso, el caballo alado, con un freno de oro que le dio Atenea. Mucho después, el geógrafo Estrabón hablará de mil servidoras de la diosa; los historiadores de hoy dudan de esa cifra.',c.x+8,c.z+30,Math.PI);}
   {const p=I.peir;blockBuilding({name:'Fuente Pirene',x:p.x,z:p.z-3,rot:0,w:18,d:7,h:4.5,mat:M.limestone});for(let i=0;i<6;i++)box(1.8,2.6,0.2,M.dark,p.x-7.5+i*3,p.h+1.3,p.z+0.6);pool(p.x,p.z+4,16,4,p.h);
    place('pirene','Fuente Pirene','ΠΕΙΡΗΝΗ','La gran fuente de la ciudad baja, con seis cámaras abiertas a un estanque. Según el mito, Pirene lloró tanto a su hijo, muerto por Ártemis sin querer, que se convirtió en manantial. Los corintios presumen de que su agua es la mejor de Grecia; en ella bebía Pegaso.',p.x+14,p.z+6,0);}
   stoa({name:'Pórtico del mercado',x:t.x+20,z:t.z-30,rot:0,len:40,depth:9,colH:4.6,colD:0.6});
   {const sh=shoreAlong(I.x+150,I.z-200,0,-1,400);box(5,0.4,46,M.limestone,sh[0],terrainH(sh[0],sh[1]+20)+0.15,sh[1]+20);for(let i=0;i<14;i++)box(0.25,0.08,0.4,lam('#7a6a50'),sh[0]+(i%2?1.5:-1.5),terrainH(sh[0],sh[1]+4+i*3)+0.4,sh[1]+4+i*3);
    const cart=grp(sh[0],terrainH(sh[0],sh[1]+30)+0.5,sh[1]+30,0);box(3.2,0.8,9,M.wood,0,0.6,0,cart);for(const s of[-1,1])for(const z2 of[-3,3]){const w=new THREE.Mesh(new THREE.CylinderGeometry(0.6,0.6,0.3,12),M.wood);w.rotation.z=Math.PI/2;w.position.set(s*1.7,0.6,z2);cart.add(w);}addBox(sh[0],sh[1]+30,3.2,9,0);
    makeShip(sh[0]-60,sh[1]-50,Math.PI/2);
    place('diolkos','El diolkos','ΔΙΟΛΚΟΣ','Un camino empedrado de unos seis kilómetros cruza el Istmo, desde el puerto del golfo de Corinto hasta el del golfo Sarónico. Por él se arrastran en carros las mercancías, y a veces barcos enteros, para no tener que rodear el Peloponeso por el temido cabo Malea. Lo hizo construir, según la tradición, el tirano Periandro, hacia el 600. Corinto cobra por usarlo: de ahí buena parte de su riqueza.',sh[0]+10,sh[1]+40,0);}
   place('guerra_corintia','La guerra de Corinto','ΚΟΡΙΝΘΙΑΚΟΣ ΠΟΛΕΜΟΣ','Durante ocho años, desde el 395, Corinto, Atenas, Tebas y Argos lucharon contra Esparta, y gran parte de los combates fueron aquí, en el Istmo. En el 392 Corinto y Argos llegaron a unirse en un solo Estado. La paz del Rey, de este mismo año, obliga a deshacer la unión: vuelven los desterrados partidarios de Esparta, y muchos temen venganzas.',t.x-10,t.z+40,0);
   place('lequeo_390','Los muros largos y la mora destruida','ΙΦΙΚΡΑΤΗΣ','Unos muros largos unen Corinto con su puerto de Lequeo. En el 392 los espartanos abrieron una brecha en ellos y llegaron al puerto. Dos años después, en el 390, aquí mismo, el ateniense Ifícrates y sus peltastas, soldados ligeros con escudos pequeños y jabalinas, acosaron a una mora espartana, un batallón de unos seiscientos hoplitas, hasta matar a unos doscientos cincuenta. Nadie había visto algo así: tropas ligeras derrotando a los temidos espartanos.',t.x+40,t.z-60,0);
   place('potros','Los potros de Corinto','ΠΩΛΟΙ','Las monedas de plata de Corinto llevan a Pegaso, el caballo alado, y a la letra koppa, la inicial antigua del nombre de la ciudad. Por eso la gente las llama «potros». Se aceptan en todo el Mediterráneo occidental, de Sicilia a Italia, porque Corinto fundó allí colonias como Siracusa.',t.x+24,t.z-40,0);
   place('glauce','Fuente de Glauce','ΓΛΑΥΚΗ','Según el mito, Jasón dejó a Medea para casarse con Glauce, la hija del rey de Corinto. Medea le regaló un vestido envenenado que ardió sobre su cuerpo; la muchacha se arrojó a esta fuente buscando alivio. Cerca está la tumba de los hijos de Medea: los corintios cuentan, como recoge Pausanias, que fueron ellos quienes los mataron, y que Eurípides lo cambió en su tragedia.',t.x-34,t.z-24,0);
   greekTheatre({x:t.x-70,z:t.z+95,rot:0,R0:8,R1:30,H:10,name:'Teatro de Corinto'});
   destHouses(I,t.x,t.z,45,160,false);greekArrive(I,'Corinto');NPC_POS.nicandro=[t.x+24,t.z-18,Math.PI];
   islandVillagers(I,t.x+30,t.z+10,5,['«No todos pueden ir a Corinto», dice el refrán. Aquí todo es caro, sobre todo la diversión.','Los barcos pasan el Istmo por el diolkos: sale más barato que rodear el cabo Malea.','Con la paz vuelven los desterrados amigos de Esparta. Mi vecino ya ha cerrado la puerta con tranca.','Nuestros bronces y nuestros vasos se venden en todo el mar, de Sicilia a Asia.']);}
  // ------------------------------------------------ Platea
  {const I=G('platea'),t=I.town,wm=lam('#a8987a');
   for(let i=0;i<48;i++){const t0=i/48*TAU,t1=(i+1)/48*TAU;if(R()<0.35)continue;const r=110,ax=t.x+Math.cos(t0)*r,az=t.z+Math.sin(t0)*r,bx=t.x+Math.cos(t1)*r,bz=t.z+Math.sin(t1)*r,hh=rr(0.6,2.6),len=Math.hypot(bx-ax,bz-az);
     box(2,hh+2,len,wm,(ax+bx)/2,terrainH(ax,az)+hh/2-1,(az+bz)/2).rotation.y=Math.atan2(bx-ax,bz-az);addSeg(ax,az,bx,bz,1);}
   destHouses(I,t.x,t.z,22,80,false);
   for(let i=0;i<6;i++){const x=t.x+rr(-60,60),z=t.z+rr(-60,60);if(!isFree(x,z,6))continue;const g=grp(x,terrainH(x,z),z,R()*3);for(const[px,pz]of[[-4,-4],[4,-4],[-4,4],[4,4]])box(0.2,5,0.2,M.wood,px,2.5,pz,g);box(8.4,0.2,0.2,M.wood,0,4.6,-4,g);box(8.4,0.2,0.2,M.wood,0,4.6,4,g);box(7,1,0.6,lam('#bba98a'),0,0.5,-4,g);box(3,0.8,0.8,lam('#bba98a'),2,0.4,1,g);addBox(x,z,9,9,g.rotation.y);}
   place('platea_vuelta','Platea vuelve a levantarse','ΠΛΑΤΑΙΑΙ','Platea fue siempre la fiel aliada de Atenas: fue la única ciudad que luchó a su lado en Maratón. En el 427, tras dos años de asedio, espartanos y tebanos la tomaron, ejecutaron a sus defensores y la arrasaron. Los supervivientes recibieron la ciudadanía ateniense. Ahora, con la paz del Rey, los espartanos han decidido reconstruirla, también para debilitar a Tebas. Los plateenses vuelven a casa después de cuarenta años.',t.x+20,t.z+40,0);
   {const h=I.hera;temple({name:'Templo de Hera de Platea',x:h.x,z:h.z,rot:Math.PI/2,W:13,L:30,nW:6,nL:13,colD:0.95,colH:5.6,gy:h.h,cella:{w:8,l:17,door:2.6}});
    place('hereo_platea','Templo de Hera','ΗΡΑΙΟΝ','Después de arrasar Platea, los tebanos construyeron aquí, con las piedras de la ciudad, un templo de Hera de cien pies de largo y una gran hospedería para los peregrinos, como cuenta Tucídides. Los plateenses que vuelven tendrán que rezar en el templo que levantaron sus enemigos.',h.x+18,h.z+6,0);}
   {const a=I.altar;box(6,1.4,4,M.marble,a.x,a.h+0.7,a.z);addBox(a.x,a.z,6,4,0);statue(a.x,a.h+1.4,a.z-1,0,1.2,'bronze');
    place('eleuterias','Altar de Zeus Liberador','ΖΕΥΣ ΕΛΕΥΘΕΡΙΟΣ','Tras vencer a los persas en el 479, los griegos levantaron aquí un altar a Zeus Liberador e instituyeron las Eleuterias, unas fiestas cada cuatro años en honor de los que murieron por la libertad de Grecia. Los plateenses quedaron encargados de cuidar las tumbas y celebrar cada año un sacrificio por los caídos.',a.x+10,a.z+4,0);}
   {const b=I.tombs;tumulus(b.x,b.z,9,4);tumulus(b.x+24,b.z-8,8,3.6);tumulus(b.x-20,b.z+12,7,3);
    place('batalla_platea','La batalla de Platea','ΜΑΧΗ','En esta llanura, en el verano del 479, el ejército griego, de más de cien mil hombres según Heródoto y mandado por el espartano Pausanias, derrotó al ejército persa de Mardonio, que murió en el combate. Fue el final de la invasión de Jerjes. Los muertos de cada ciudad se enterraron en túmulos propios: los de Esparta, los de Atenas, los de Tegea.',b.x+16,b.z-18,0);}
   greekArrive(I,'Platea');NPC_POS.eutiades=[t.x+12,t.z+12,0];
   islandVillagers(I,t.x-20,t.z+10,5,['Mi padre nació en Atenas, en el exilio. Yo no había visto nunca esta tierra.','Los tebanos nos miran desde el otro lado del Asopo. No nos quieren aquí.','Cada piedra de este muro la he puesto con mis manos. Y la de al lado, mi hermano.','Dicen que los espartanos nos ayudan. Hace cuarenta años nos degollaron.']);}
  // ------------------------------------------------ Delfos
  {const I=G('delfos'),T=I.temple;
   temple({name:'Templo de Apolo de Delfos',x:T.x,z:T.z,rot:0,W:24,L:58,nW:6,nL:15,colD:1.9,colH:10.4,gy:T.h,roofMat:M.tile,sculpt:9,cella:{w:15,l:36,door:3.6,antis:4,antisCols:true}});
   {const om=new THREE.Mesh(new THREE.SphereGeometry(0.9,16,12),lam('#cfc4ab'));om.scale.y=1.3;om.position.set(T.x+8,T.h+1.1,T.z+34);scene.add(om);addCirc(T.x+8,T.z+34,1);
    place('omfalo','El ombligo del mundo','ΟΜΦΑΛΟΣ','Zeus soltó dos águilas, una en cada extremo del mundo, y se encontraron aquí: Delfos es el centro de la tierra. Lo marca esta piedra en forma de huevo, el ómfalo, cubierta con una red de lana. Dentro del templo hay otro, junto al lugar de las profecías.',T.x+12,T.z+36,0);}
   place('templo_apolo_delfos','El templo de Apolo','ΝΑΟΣ ΑΠΟΛΛΩΝΟΣ','El templo que ves lo reconstruyó a finales del siglo VI la familia ateniense de los Alcmeónidas, que pagó de su bolsillo una fachada de mármol. En el vestíbulo están escritas las máximas de los sabios: «Conócete a ti mismo» y «Nada en exceso». Trece años después de tu visita, en el 373, un terremoto lo derribará y habrá que levantarlo de nuevo.',T.x-14,T.z+36,0);
   place('pitia','La Pitia','ΠΥΘΙΑ','En lo más hondo del templo, en el ádyton, una mujer de Delfos, la Pitia, se sienta en un trípode y habla en nombre de Apolo. Antes se purifica en la fuente Castalia y quema hojas de laurel. Solo profetiza algunos días al año; los sacerdotes ponen en verso sus respuestas, a menudo ambiguas. Autores muy posteriores hablarán de vapores que salían de una grieta; la ciencia moderna lo sigue discutiendo.',T.x+14,T.z-34,Math.PI);
   {const c=I.col;const g=grp(c.x,c.h,c.z,0);box(2.2,0.8,2.2,M.limestone,0,0.4,0,g);for(let k=0;k<3;k++){const pts=[];for(let i=0;i<=60;i++){const tt=i/60;pts.push(new THREE.Vector3(Math.cos(tt*TAU*4+k*TAU/3)*0.35,0.8+tt*6,Math.sin(tt*TAU*4+k*TAU/3)*0.35));}const tb=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts),80,0.16,6),M.bronze);tb.castShadow=true;g.add(tb);}
    const tri=new THREE.Mesh(new THREE.CylinderGeometry(1.2,0.5,1,12,1,true),M.gold);tri.position.y=7.3;g.add(tri);for(let k=0;k<3;k++){const l=box(0.08,2.2,0.08,M.gold,Math.cos(k*TAU/3)*0.9,6.6,Math.sin(k*TAU/3)*0.9,g);}addCirc(c.x,c.z,1.4);
    place('columna_serpientes','La columna de las serpientes','ΤΡΙΠΟΥΣ','Tras la victoria de Platea en el 479, los griegos dedicaron a Apolo un trípode de oro sobre tres serpientes de bronce entrelazadas, fundidas con las armas de los persas. En las serpientes están grabados los nombres de las treinta y una ciudades que lucharon. El regente espartano Pausanias hizo grabar al principio un epigrama solo con su nombre; los espartanos lo borraron. Ocho siglos después, Constantino se llevará la columna a Constantinopla.',c.x+5,c.z+3,0);}
   {const t=I.treas;blockBuilding({name:'Tesoro de los atenienses',x:t.x,z:t.z,rot:0,w:6.7,d:9.7,h:5.2,mat:M.marble});for(const s of[-1,1])addColumn(t.x+s*1.5,t.h,t.z+5.2,0.3,4.2,0,'doric');
    place('tesoro_atenienses','Tesoro de los atenienses','ΘΗΣΑΥΡΟΣ ΑΘΗΝΑΙΩΝ','Un pequeño templo de mármol de hacia el 500-490 a.C. donde Atenas guarda sus ofrendas a Apolo. Sus metopas cuentan, frente a frente, los trabajos de Heracles y los de Teseo, el héroe ateniense. Pausanias dirá que se pagó con el botín de Maratón; los arqueólogos no se ponen de acuerdo en la fecha.',t.x+8,t.z+8,0);}
   place('stoa_atenienses','El pórtico de los atenienses','ΣΤΟΑ ΑΘΗΝΑΙΩΝ','Al pie del muro que sostiene la terraza del templo, Atenas levantó un pórtico ligero de columnas jónicas. Su inscripción dice que los atenienses lo dedicaron con las amarras y los espolones tomados al enemigo, probablemente a los persas. El muro de detrás es de bloques poligonales encajados sin argamasa, como un rompecabezas. Siglos más tarde se llenará de inscripciones: actas de liberación de esclavos puestos bajo la protección del dios.',I.treas.x-6,I.treas.z+22,0);
   {const c=I.cast;pool(c.x,c.z+3,10,5,c.h);for(let i=0;i<8;i++){const r=new THREE.Mesh(new THREE.DodecahedronGeometry(rr(1.5,3),0),M.stone);r.position.set(c.x+rr(-8,8),c.h+rr(0,4),c.z-6+rr(-2,2));scene.add(r);}addSeg(c.x-9,c.z-5,c.x+9,c.z-5,1.5);
    place('castalia','La fuente Castalia','ΚΑΣΤΑΛΙΑ','El agua que baja de las rocas Fedríades, entre dos paredes de piedra. Aquí se purifican los que vienen a consultar el oráculo, los sacerdotes y la propia Pitia. Los poetas dirán que su agua inspira: por eso las Musas viven en el Parnaso, sobre tu cabeza.',c.x+10,c.z+8,0);}
   {const s=I.stad;stadiumG(s.x,s.z,Math.PI/2,120,24,'Estadio de Delfos');}
   greekArrive(I,'Delfos');NPC_POS.teodoro=[T.x+20,T.z+42,Math.PI];
   islandVillagers(I,T.x-20,T.z+60,5,['Las preguntas de las ciudades pasan antes que las tuyas. Y antes aún, las de quienes tienen el derecho de precedencia.','Si la cabra no tiembla cuando le echan agua fría, la Pitia no habla hoy. Vuelve mañana.','Aquí vienen de todas partes: hasta los reyes de Lidia mandaban oro.','Cada cuatro años, en los Juegos Píticos, se compite en canto con la cítara, no solo en carreras.']);}
  // ------------------------------------------------ Argos
  {const I=G('argos'),t=I.town;
   {const l=I.lar;ringWall(l.x,l.z,34,[Math.PI/2],lam('#a99d84'),6,4);temple({name:'Templo de Zeus Larisio',x:l.x,z:l.z,rot:Math.PI/2,W:8,L:14,nW:4,prostyle:true,colD:0.6,colH:4.4,gy:l.h,cella:{w:7,l:8,door:2.2}});
    place('larisa','La Larisa','ΛΑΡΙΣΑ','La acrópolis de Argos, un monte cónico con murallas y templos de Zeus y de Atenea. Al lado está la colina más baja del Aspis, con el santuario de Apolo, que da oráculos. Según el mito, Argos la fundó Ínaco, el dios del río, y aquí reinaron Dánao, llegado de Egipto con sus cincuenta hijas, y Perseo.',l.x+8,l.z+40,Math.PI);}
   {const h=I.thea,g=grp(h.x,h.h,h.z,0);for(let i=0;i<14;i++){box(46,0.45,0.85,lam(i%2?'#cfc3aa':'#bfb39a'),0,0.22+i*0.42,-i*0.8,g);}addBox(h.x,h.z-5.6,46,11.6,0);
    place('teatro_argos','El teatro de las gradas rectas','ΘΕΑΤΡΟΝ','Aquí se reúne la asamblea de Argos: unas gradas rectas talladas en la roca de la ladera, para unas dos mil quinientas personas. El gran teatro curvo que verá quien venga dentro de un siglo todavía no existe. Argos es una democracia desde el siglo V, enemiga de Esparta, que manda en el Peloponeso.',h.x+28,h.z+8,0);}
   temple({name:'Templo de Apolo Licio',x:t.x+40,z:t.z+40,rot:Math.PI/2,W:11,L:22,nW:6,nL:11,colD:0.85,colH:5.4,cella:{w:7,l:12,door:2.4}});
   place('apolo_licio','Apolo Licio','ΑΠΟΛΛΩΝ ΛΥΚΕΙΟΣ','El templo más importante del ágora de Argos. Cuenta Pausanias que, cuando Dánao llegó de Egipto, se disputó el trono con el rey Gelánor, y el pueblo no sabía a quién elegir. Al amanecer, un lobo bajó del monte, atacó a un rebaño y mató al toro que lo guiaba. Los argivos vieron en el lobo, un forastero, a Dánao, y le dieron el reino. Dánao, agradecido, fundó este templo a Apolo «del lobo».',t.x+40,t.z+66,0);
   {const x=t.x-40,z=t.z+70;temple({name:'Santuario de Afrodita',x,z,rot:0,W:7,L:12,nW:4,prostyle:true,colD:0.55,colH:4,cella:{w:6,l:7,door:2}});statue(x+8,floorAt(x+8,z+10),z+10,Math.PI,1.1,'marble');
    place('telesila','Telesila','ΤΕΛΕΣΙΛΛΑ','Delante del santuario de Afrodita hay una estatua de Telesila, una poetisa de Argos. Hacia el 494, cuando el rey espartano Cleómenes mató a casi todos los hombres de la ciudad, ella armó a las mujeres, a los esclavos y a los viejos, y defendió las murallas. Así lo cuenta Pausanias. En la estatua, sus libros están a sus pies y ella se pone un casco.',x+12,z+12,0);}
   place('policleto','Los broncistas de Argos','ΠΟΛΥΚΛΕΙΤΟΣ','Argos es la ciudad de Policleto, que trabajó hace cincuenta años: escribió un tratado, el Canon, con las proporciones perfectas del cuerpo humano, y lo puso en práctica en una estatua de bronce, el Portador de lanza. Sus discípulos siguen fundiendo bronces para toda Grecia. Suya es también la gran Hera de oro y marfil del Hereo, junto a Micenas.',t.x,t.z+20,0);
   destHouses(I,t.x,t.z,45,150,false);greekArrive(I,'Argos');NPC_POS.dionisodoro=[t.x+10,t.z+30,Math.PI];
   islandVillagers(I,t.x+20,t.z-10,5,['Argos ya era reina cuando los espartanos todavía eran pastores.','Danao llegó de Egipto con sus cincuenta hijas, y aquí se quedó.','Se acabó la unión con Corinto. Lo ha mandado el rey de Persia. ¡El rey de Persia!','Mi taller funde bronces para Olimpia y para Delfos. Ven a verlo si quieres saber cómo se hace una estatua.']);}
  // ------------------------------------------------ Epidauro
  {const I=G('epidauro'),s=I.sanct;
   temple({name:'Templo antiguo de Asclepio',x:s.x-20,z:s.z-10,rot:Math.PI/2,W:8,L:15,nW:4,prostyle:true,colD:0.6,colH:4.6,gy:s.h,cella:{w:7,l:9,door:2.2}});
   box(7,1.2,3,M.marble,s.x-2,s.h+0.6,s.z-10);addBox(s.x-2,s.z-10,7,3,0);
   stoa({name:'Pórtico de los sueños',x:s.x+10,z:s.z-50,rot:0,len:44,depth:9,colH:4.4,colD:0.55});
   {const x=s.x+30,z=s.z+20;box(13.2,0.8,24.5,M.limestone,x,s.h+0.4,z);addPlat(x,z,13.2,24.5,0,s.h+0.8);for(let i=0;i<10;i++){box(rr(1.4,2.4),rr(0.8,1.4),rr(1.4,3),M.marble,x+rr(-14,14)+(i%2?16:-16)*0.6,s.h+0.6,z+rr(-14,14));}
    const cr=grp(x+10,s.h,z-16,0);const l1=box(0.35,12,0.35,M.wood,-2,5.6,0,cr);l1.rotation.z=0.2;const l2=box(0.35,12,0.35,M.wood,2,5.6,0,cr);l2.rotation.z=-0.2;box(0.25,0.25,9,M.wood,0,11,2,cr);addCirc(x+10,z-16,2.2);
    footprints.push({x,z,w:13.2,d:24.5,a:0,c:'#d8ccb0',name:'Obras del templo nuevo'});
    place('templo_nuevo','Las obras del templo nuevo','ΝΑΟΣ ΚΑΙΝΟΣ','El santuario crece y los epidaurios preparan un templo nuevo para Asclepio, más grande y de mármol. Las cuentas de la obra, grabadas en piedra, nos dirán que el arquitecto fue Teodoto y que la estatua de oro y marfil del dios la hizo Trasimedes de Paros. Las obras se harán en los años siguientes a tu visita.',x+12,z+14,0);}
   place('asclepieion','El santuario de Asclepio','ΑΣΚΛΗΠΙΕΙΟΝ','Asclepio, hijo de Apolo, es el dios que cura. Los enfermos llegan de toda Grecia, se purifican, ofrecen un sacrificio y pasan la noche en un pórtico sagrado: el dios se les aparece en sueños y los cura, o les dice qué hacer. Dentro del recinto está prohibido nacer y morir. Desde el 420 el dios tiene también santuario en Atenas, junto al teatro: lo recibió en su casa el poeta Sófocles.',s.x-6,s.z+6,0);
   place('suenos_epidauro','El pórtico de los sueños','ΕΓΚΟΙΜΗΤΗΡΙΟΝ','Aquí duermen los enfermos sobre pieles de animales sacrificados, esperando el sueño que los cure. Por el santuario se pasean perros y serpientes sagradas, inofensivas: a veces lamen las heridas de los que duermen. Más adelante, en este mismo siglo, se grabarán en estelas los relatos de las curaciones: ciegos que ven, cojos que andan, una mujer embarazada durante cinco años.',s.x+10,s.z-38,0);
   for(let i=0;i<3;i++){const d=makeBeast('lobo',scene,s.x+rr(-20,20),s.z+rr(-20,10),R()*TAU);d.position.y=s.h;d.scale.setScalar(0.8);}
   {const m=I.mal;temple({name:'Santuario de Apolo Maleatas',x:m.x,z:m.z,rot:Math.PI/2,W:7,L:12,nW:4,prostyle:true,colD:0.5,colH:4,gy:m.h,cella:{w:6,l:7,door:2}});
    place('apolo_maleatas','Apolo Maleatas','ΑΠΟΛΛΩΝ ΜΑΛΕΑΤΑΣ','En la colina del Cinortio está el santuario más antiguo de Epidauro, el de Apolo Maleatas. El culto de su hijo Asclepio, abajo en el valle, empezó a su sombra. Los peregrinos hacen ofrendas a los dos.',m.x+10,m.z+10,0);}
   greekArrive(I,'Epidauro');NPC_POS.sostrato=[s.x-6,s.z-22,0];
   islandVillagers(I,s.x+20,s.z+40,5,['Duerme en el pórtico y cuéntale al sacerdote lo que sueñes.','Llevo tres noches aquí. Esta noche, seguro que viene el dios.','Prohibido nacer y morir dentro del recinto: a las parturientas y a los moribundos los sacan fuera.','Mi hijo vino ciego de un ojo. Ahora ve. Bueno, un poco.']);}
  // ------------------------------------------------ Mantinea
  {const I=G('mantinea'),t=I.town;
   ringWall(t.x,t.z,150,[0.4,2,3.5,5.1],lam('#a8805a'),8,5,M.limestone);
   {const pts=[];for(let i=0;i<=30;i++){const tt=i/30;pts.push([t.x+Math.sin(tt*5)*20,t.z-I.R*1.1+tt*I.R*2.2]);}riverRibbon(pts,9);}
   temple({name:'Templo de Hera de Mantinea',x:t.x+30,z:t.z-30,rot:Math.PI/2,W:10,L:20,nW:6,nL:11,colD:0.75,colH:5,cella:{w:7,l:11,door:2.4}});
   blockBuilding({name:'Consejo de Mantinea',x:t.x-30,z:t.z-34,rot:0,w:18,d:14,h:5,door:true});
   place('muralla_mantinea','Las murallas de adobe','ΤΕΙΧΗ','Las murallas de Mantinea son de adobe sobre un zócalo de piedra, y el río Ofis atraviesa la ciudad. Esparta, que manda en el Peloponeso desde la paz del Rey, exige ahora que los mantineos derriben sus murallas, porque los considera poco leales. Dentro de un año, en el 385, el rey Agesípolis represará el río: el agua deshará el adobe y obligará a los mantineos a dispersarse en aldeas. Las murallas de piedra que se ven hoy son de la ciudad refundada en el 370.',t.x+40,t.z+20,0);
   place('batalla_mantinea','La batalla de Mantinea','ΜΑΧΗ','En el 418, en esta llanura, el ejército espartano del rey Agis derrotó a Argos, Mantinea y Atenas en la mayor batalla de hoplitas de la guerra del Peloponeso. Tucídides la cuenta paso a paso: cómo las líneas se desplazaban hacia la derecha porque cada soldado buscaba cubrirse con el escudo del vecino.',t.x-60,t.z+70,0);
   place('diotima','Diotima de Mantinea','ΔΙΟΤΙΜΑ','En el Banquete de Platón, Sócrates cuenta que una sacerdotisa de Mantinea, Diotima, le enseñó qué es el amor: un deseo de belleza que empieza por un cuerpo y sube hasta la belleza misma. Nadie sabe si existió o si es una invención de Platón. Platón escribirá ese diálogo en estos mismos años.',t.x+50,t.z-60,0);
   place('poseidon_hipio','Poseidón Hipio','ΠΟΣΕΙΔΩΝ ΙΠΠΙΟΣ','A poca distancia de la ciudad está el santuario de Poseidón Hipio, «el de los caballos», el más venerado de Mantinea. Nadie puede cruzar su umbral: lo cierra solo un cordón de lana. Cuentan que un rey antiguo, Épito, lo cortó y entró, y una ola de agua salada lo dejó ciego. Los mantineos llevan al dios en sus escudos como emblema.',t.x-70,t.z-40,0);
   destHouses(I,t.x,t.z,50,120,false,{inside:(x,z)=>Math.hypot(x-t.x,z-t.z)<135});greekArrive(I,'Mantinea');NPC_POS.calias_mantinea=[t.x-24,t.z-20,0];
   islandVillagers(I,t.x+10,t.z+30,5,['Los espartanos quieren que derribemos las murallas. ¿Y luego qué, vivir en aldeas como los abuelos?','Aquí votamos todos, pero los cargos los eligen unos pocos. Así nadie deja el campo para ir a la asamblea.','Los arcadios siempre acabamos luchando por otros: los que pagan bien nos contratan.','El Ofis se desborda en primavera. Un día nos va a dar un disgusto.']);}
  // ------------------------------------------------ Olimpia
  {const I=G('olimpia'),A=I.altis;
   temple({name:'Templo de Zeus',x:A.x+20,z:A.z+20,rot:Math.PI/2,W:27.7,L:64.1,nW:6,nL:13,colD:2.2,colH:10.4,gy:A.h,roofMat:M.tile,sculpt:9,cella:{w:16,l:40,door:4,antis:4.5,antisCols:true}});
   temple({name:'Hereo de Olimpia',x:A.x-60,z:A.z-70,rot:Math.PI/2,W:18.75,L:50,nW:6,nL:16,colD:1.2,colH:5.2,gy:A.h,cella:{w:11,l:32,door:2.8}});
   {const pl=tumulus(A.x-30,A.z-25,9,2.6,'#8a8a5a');}
   {const x=A.x-14,z=A.z-48,gy=floorAt(x,z);const base=new THREE.Mesh(new THREE.CylinderGeometry(6,6.4,1.2,20),M.limestone);base.position.set(x,gy+0.6,z);scene.add(base);
    const ash=new THREE.Mesh(new THREE.ConeGeometry(4.2,6.2,18),lam('#8b8378'));ash.position.set(x,gy+1.2+3.1,z);ash.scale.set(1,1,0.8);scene.add(ash);addCirc(x,z,6.4);
    place('altar_cenizas','El gran altar de Zeus','ΒΩΜΟΣ','El altar más sagrado de Olimpia no es de piedra: es un montón de ceniza de los muslos de las víctimas quemadas durante siglos, de más de seis metros de alto. Pausanias cuenta que los sacrificios se hacen abajo, en una plataforma de piedra, y que solo los hombres pueden subir a la cima para quemar las ofrendas. Cada año, los adivinos mezclan la ceniza del hogar del pritaneo con agua del Alfeo, la única que sirve, y cubren el altar.',x+9,z+4,0);}
   for(let i=0;i<8;i++){const x=A.x-60+i*14,z=A.z-120;blockBuilding({name:'Tesoro',x,z,rot:0,w:10,d:12,h:4.6,mat:M.limestone});}
   for(let i=0;i<6;i++){const x=A.x-50+i*12,z=A.z-100,gy=floorAt(x,z);box(1.4,1.6,1.4,M.limestone,x,gy+0.8,z);statue(x,gy+1.6,z,0,1.2,'bronze');addBox(x,z,1.4,1.4,0);}
   {const lw=lam('#b9aa8a');for(const[x0,z0,x1,z1]of[[-110,-150,110,-150],[110,-150,110,110],[110,110,-110,110],[-110,110,-110,-150]]){const L2=Math.hypot(x1-x0,z1-z0),n=Math.round(L2/20);for(let i=0;i<n;i++){if(i===Math.floor(n/2))continue;const ax=A.x+lerp(x0,x1,i/n),az=A.z+lerp(z0,z1,i/n),bx=A.x+lerp(x0,x1,(i+1)/n),bz=A.z+lerp(z0,z1,(i+1)/n);box(0.8,1.6,Math.hypot(bx-ax,bz-az),lw,(ax+bx)/2,terrainH(ax,az)+0.6,(az+bz)/2).rotation.y=Math.atan2(bx-ax,bz-az);addSeg(ax,az,bx,bz,0.4);}}}
   {const s=I.stad;stadiumG(s.x,s.z,Math.PI/2,192,30,'Estadio de Olimpia');}
   {const w=I.ws;blockBuilding({name:'Taller de Fidias',x:w.x,z:w.z,rot:0,w:14.5,d:32,h:12,mat:M.limestone,door:true});}
   {const pts=[];for(let i=0;i<=30;i++){const tt=i/30;pts.push([A.x-I.R*1.2+tt*I.R*2.4,A.z+230+Math.sin(tt*6)*20]);}riverRibbon(pts,34);}
   // el Altis, el bosque sagrado: acebuches (de ellos se cortan las coronas), plátanos y álamos blancos (la única leña de los sacrificios a Zeus)
   try{groveIn(I,A.x,A.z-20,210,250,110,{wolive:3,plane:2,wpoplar:2},55.5);
     if(GLB.ok){const kx=A.x+20,kz=A.z-18;placeModules('T_olive',[{x:kx,y:floorAt(kx,kz),z:kz,a:0.7,sx:2.1,sy:1.9,sz:2.1,cf:new THREE.Color('#6e7a52')}],{far:1600});addCirc(kx,kz,1.2);}
     place('altis_olimpia','El Altis, el bosque sagrado','ΑΛΤΙΣ','Altis quiere decir «bosque sagrado»: así llaman los eleos al recinto de Zeus, lleno de acebuches, plátanos y álamos. Detrás del templo crece el acebuche Kallistéphanos, «el de las bellas coronas»: un niño con padre y madre vivos corta con una hoz de oro las ramas para las coronas de los vencedores. Para los sacrificios a Zeus solo se usa leña de álamo blanco, porque dicen que Heracles lo trajo de la orilla del Aqueronte (Pausanias 5, 14, 2 y 5, 15, 3).',...(()=>{const f=findFree(A.x-70,A.z+50,2);return[f[0],f[1]];})(),0);}catch(e){console.warn('altis',e);}
   place('zeus_olimpia','El templo de Zeus','ΝΑΟΣ ΔΙΟΣ','El gran templo dórico de Zeus, terminado hacia el 456 por el arquitecto Libón de Élide. En el frontón este, la carrera de carros de Pélope y Enómao; en el oeste, la lucha de lápitas y centauros; en las metopas, los doce trabajos de Heracles. Dentro está sentado el Zeus de oro y marfil que Fidias hizo hacia el 430: tan grande que, si se levantara, rompería el techo.',A.x+20,A.z+60,0);
   place('hereo_olimpia','El Hereo','ΗΡΑΙΟΝ','El templo de Hera, de hacia el 600, es uno de los más antiguos de Grecia. Al principio sus columnas eran de madera y se han ido cambiando por otras de piedra a medida que se pudrían: por eso no hay dos iguales. Pausanias todavía verá una de roble, siglos después.',A.x-60,A.z-38,0);
   place('estadio_olimpia','El estadio','ΣΤΑΔΙΟΝ','La pista mide un estadio, seiscientos pies: unos 192 metros. Aquí se corre la carrera más antigua de los Juegos, que se celebran cada cuatro años en honor de Zeus. Los últimos fueron hace dos años, en el 388; los próximos, dentro de dos. Durante los Juegos hay una tregua sagrada en toda Grecia. Los espectadores se sientan en los taludes de tierra; las mujeres casadas no pueden asistir.',I.stad.x-20,I.stad.z+30,0);
   place('zanes','Los Zanes','ΖΑΝΕΣ','Estas estatuas de bronce de Zeus son nuevas: en los últimos Juegos, en el 388, el boxeador Eupolo de Tesalia sobornó a tres rivales para que se dejaran ganar. Los jueces de Élide les impusieron una multa y con ella se pagaron estas seis estatuas, con inscripciones que avisan de que en Olimpia la victoria se gana con los pies y con la fuerza, no con dinero.',A.x-50,A.z-92,0);
   place('lisias_olimpia','El discurso de Lisias','ΟΛΥΜΠΙΚΟΣ','En los Juegos del 388, el orador ateniense Lisias pronunció aquí un discurso: pidió a los griegos que dejaran de pelearse entre ellos y se unieran contra el rey de Persia y contra Dionisio, el tirano de Siracusa, que había enviado una embajada con tiendas lujosas. Parte del público, enardecido, asaltó las tiendas.',A.x+60,A.z-40,0);
   place('taller_fidias','El taller de Fidias','ΕΡΓΑΣΤΗΡΙΟΝ','En este edificio, del mismo tamaño que la cella del templo, Fidias y sus ayudantes trabajaron el oro, el marfil y el vidrio de la estatua de Zeus. En el siglo XX los arqueólogos encontrarán aquí moldes de arcilla, herramientas y una taza con una inscripción: «Soy de Fidias».',I.ws.x+12,I.ws.z+18,0);
   greekArrive(I,'Olimpia');NPC_POS.aristarco=[A.x+40,A.z+60,Math.PI];
   islandVillagers(I,A.x+40,A.z+80,5,['Los atletas entrenan un mes entero en Élide antes de los Juegos, bajo la mirada de los jueces.','Nosotros, los eleos, organizamos los Juegos. Y nadie lo hace mejor.','Esas estatuas nuevas de Zeus las han pagado los tramposos.','Si vienes en los Juegos, trae sombrero y agua: aquí en verano se derrite hasta el bronce.']);}
  // ------------------------------------------------ Termópilas
  {const I=G('termopilas');
   {const a=I.anth;temple({name:'Santuario de Deméter Anfictiónide',x:a.x,z:a.z-8,rot:Math.PI/2,W:10,L:18,nW:4,prostyle:true,colD:0.7,colH:5,gy:a.h,cella:{w:8,l:11,door:2.4}});
    for(let i=0;i<4;i++)box(14,0.6,1.2,M.limestone,a.x,a.h+0.3+i*0.6,a.z+14+i*1.4);
    place('antela','Antela y la Anfictionía','ΑΝΘΗΛΗ','En la aldea de Antela, a la entrada occidental del paso, está el santuario de Deméter Anfictiónide. Aquí se reúnen cada otoño los delegados de la Anfictionía, la liga de doce pueblos vecinos que administra también el santuario de Delfos (en primavera se reúnen allí). Tienen sus asientos de piedra junto al templo. Heródoto cuenta que el paso, aquí, era tan estrecho que solo cabía un carro.',a.x+16,a.z+6,0);}
   {const w=I.spring;pool(w.x,w.z,16,10,w.h+0.05);plume(w.x,w.h+0.5,w.z,6,6);
    place('aguas_calientes','Las puertas calientes','ΘΕΡΜΑ ΛΟΥΤΡΑ','Termópilas significa «las puertas calientes»: aquí brotan manantiales de agua caliente que huele a azufre. Los del lugar los llaman las ollas, y junto a ellos hay un altar de Heracles. Cuentan que Atenea, o Hefesto, hizo brotar estas aguas para que Heracles se bañara después de uno de sus trabajos. El agua deja en el suelo costras blancas.',w.x+12,w.z+8,0);}
   {const w=I.wall,m=lam('#a8987a');for(let i=0;i<12;i++){const z=w.z-40+i*6;if(i===6)continue;box(2.4,rr(1.4,3),6,m,w.x,terrainH(w.x,z)+0.6,z);addBox(w.x,z,2.4,6,0);}
    place('muro_focidio','El muro de los focidios','ΦΩΚΙΚΟΝ ΤΕΙΧΟΣ','Hace mucho tiempo, los focidios levantaron aquí un muro para frenar a los tesalios, y desviaron el agua caliente para encharcar el camino. En el 480 el muro estaba medio caído: los griegos de Leónidas lo repararon y se apostaron detrás. El último día salieron a combatir delante de él, donde el paso se ensanchaba.',w.x+10,w.z+10,0);}
   {const k=I.kol;const g=grp(k.x,terrainH(k.x,k.z)+0.4,k.z,-Math.PI/2),st=M.limestone;box(4,1.6,6,st,0,0.8,0,g);box(1.6,1.4,3.4,st,0,2.3,0,g);box(1.8,1.8,1.4,st,0,2.9,1.9,g);box(1,0.8,0.9,st,0,2.6,2.8,g);for(const[px,pz]of[[-0.6,-1.2],[0.6,-1.2],[-0.6,1.2],[0.6,1.2]])box(0.4,1,0.4,st,px,1.9,pz,g);box(0.25,0.25,1.4,st,0,2.6,-2.2,g).rotation.x=-0.6;
    for(let i=0;i<3;i++){const sx=k.x-8+i*8;box(1.1,2,0.3,M.marble,sx,terrainH(sx,k.z+10)+1,k.z+10);}
    place('colono_leon','El león de Leónidas','ΚΟΛΩΝΟΣ','En esta pequeña colina resistieron los últimos griegos, hasta que los persas los acribillaron a flechazos. Encima han puesto un león de piedra en honor de Leónidas, cuyo nombre significa «hijo de león». Al lado, tres estelas con epigramas. El más famoso, atribuido a Simónides, dice: «Extranjero, ve a decir a los lacedemonios que aquí yacemos, obedientes a sus leyes». Los huesos de Leónidas ya no están aquí: cuarenta años después de la batalla los llevaron a Esparta.',k.x+12,k.z+18,0);}
   {const a=I.anop;for(let i=0;i<20;i++){const px=a.x+i*1.5,pz=a.z-i*4;box(1.2,0.15,2,lam('#b5a582'),px,terrainH(px,pz)+0.1,pz);}
    place('anopea','El sendero de Anopea','ΑΝΟΠΑΙΑ','Por aquí sube el sendero que rodea el paso por el monte. Lo enseñó a los persas Efialtes, un hombre de la región, a cambio de una recompensa. Los Inmortales lo recorrieron de noche; los mil focidios que lo vigilaban arriba se retiraron a una cumbre y los dejaron pasar. Los anfictiones pusieron precio a la cabeza de Efialtes, que huyó a Tesalia. Años después lo mató un tal Atenades, por otro motivo.',a.x+10,a.z+8,0);}
   place('mar_termopilas','El mar se alejará','ΚΟΛΠΟΣ ΜΑΛΙΑΚΟΣ','Hoy el golfo Maliaco llega casi al pie del monte, y el paso, en sus puntos más estrechos, deja sitio para un solo carro. Pero el río Esperqueo arrastra tanto barro que la costa avanza año tras año. Dentro de veinticinco siglos, el mar estará a varios kilómetros, y quien venga a ver el campo de batalla encontrará una llanura ancha.',I.spring.x+40,I.spring.z+40,0);
   place('supervivientes','Los que no murieron','ΤΡΕΣΑΣ','Dos espartanos se salvaron. Aristodemo, enfermo de los ojos, no estuvo en el último combate: en Esparta lo llamaron «el que tembló», nadie le daba fuego ni le hablaba. Un año después, en Platea, luchó como un loco hasta morir, buscando la muerte. Pantites, que había ido de mensajero a Tesalia, volvió y, deshonrado, se ahorcó. Antes de la batalla, cuando alguien dijo que las flechas persas taparían el sol, el espartano Dieneces contestó: «Mejor, así lucharemos a la sombra».',I.kol.x-30,I.kol.z+30,0);
   destHouses(I,I.town.x,I.town.z,14,50,false);greekArrive(I,'Termópilas');NPC_POS.lampon=[I.anth.x+22,I.anth.z+20,0];
   islandVillagers(I,I.town.x,I.town.z+10,5,['Los viajeros siempre preguntan por el león. Luego se bañan en las aguas calientes y se van contentos.','Aquí el camino es tan estrecho que dos carros no se cruzan. Hay que esperar.','Mi abuelo decía que Efialtes era de Antícira; otros dicen que de Traquis. Nadie quiere que sea de su pueblo.','En otoño viene la Anfictionía y en Antela no cabe un alma.']);}
  // ------------------------------------------------ Maratón
  {const I=G('maraton'),t=I.town;
   {const b=I.soros;tumulus(b.x,b.z,22,9,'#8f8a5a');for(let i=0;i<10;i++){const a=-0.6+i*0.13;box(0.9,1.8,0.25,M.marble,b.x+Math.cos(a)*25,terrainH(b.x+Math.cos(a)*25,b.z+Math.sin(a)*25)+0.9,b.z+Math.sin(a)*25).rotation.y=-a+Math.PI/2;}
    place('soros','El Soros, la tumba de los atenienses','ΣΩΡΟΣ','Este túmulo de unos nueve metros de alto cubre a los 192 atenienses que murieron en la batalla. Lo normal era enterrar a los caídos en el Cerámico, a las puertas de Atenas; a estos, como honor excepcional, se los enterró aquí mismo, en el campo de batalla. Junto al túmulo están las estelas con sus nombres, tribu por tribu. Los de Maratón los honran como a héroes.',b.x+30,b.z+6,0);}
   {const b=I.plat;tumulus(b.x,b.z,11,4,'#8a8656');
    place('plateenses_maraton','La tumba de los plateenses','ΠΛΑΤΑΙΕΙΣ','Platea fue la única ciudad que acudió a ayudar a Atenas: llegó con todos sus hombres, unos mil. Sus muertos están enterrados en este segundo túmulo, junto con los esclavos, que lucharon entonces por primera vez al lado de los ciudadanos, como cuenta Pausanias.',b.x+14,b.z+4,0);}
   {const b=I.trop;box(2.4,1.2,2.4,M.marble,b.x,b.h+0.6,b.z);addColumn(b.x,b.h+1.2,b.z,0.45,7,0,'ionic');statue(b.x,b.h+8.6,b.z,0,1.3,'marble');addBox(b.x,b.z,2.4,2.4,0);
    place('trofeo_maraton','El trofeo de mármol','ΤΡΟΠΑΙΟΝ','Aquí, donde los persas empezaron a huir, los atenienses levantaron hacia el 460 una columna jónica de mármol blanco coronada por una estatua. Lo normal era colgar en un tronco las armas de los vencidos y dejar que se pudrieran; este trofeo, de piedra, debía durar para siempre. Detrás empieza la gran marisma, donde según Pausanias cayeron muchos persas al huir hacia sus naves.',b.x+10,b.z+8,0);}
   {const h=I.herak;temple({name:'Santuario de Heracles',x:h.x,z:h.z,rot:Math.PI/2,W:8,L:13,nW:4,prostyle:true,colD:0.55,colH:4.2,gy:h.h,cella:{w:7,l:8,door:2.2}});
    place('heracleion_maraton','El santuario de Heracles','ΗΡΑΚΛΕΙΟΝ','Aquí acamparon los atenienses los días antes de la batalla, en el recinto sagrado de Heracles, al pie de los montes, cerrando el camino hacia Atenas. Los de Maratón dicen que fueron los primeros griegos en honrar a Heracles como dios, y le celebran unos juegos, las Heracleas.',h.x+16,h.z+6,0);}
   place('tetrapolis','El demo de Maratón','ΤΕΤΡΑΠΟΛΙΣ','Maratón es un demo del Ática, de la tribu Ayántide. Con Énoe, Probalinto y Tricorinto forma la antigua Tetrápolis: aquí, según el mito, Teseo venció al toro de Maratón. Aquí desembarcó también Pisístrato en el 546 para hacerse tirano de Atenas; por eso su hijo Hipias guio a los persas a esta misma playa cincuenta y seis años después.',t.x+20,t.z+30,0);
   makeShip(I.x+I.R*0.62,I.z+60,Math.PI/2);
   destHouses(I,t.x,t.z,18,70,false);greekArrive(I,'Maratón');NPC_POS.hegesias=[I.soros.x+28,I.soros.z-6,-Math.PI/2];
   islandVillagers(I,t.x+10,t.z+20,5,['De noche, dicen, se oyen en la llanura relinchos de caballos y ruido de combate. Yo no salgo a comprobarlo.','Los de Maratón fuimos los primeros en honrar a Heracles como dios.','Mi bisabuelo luchó en la batalla. Cada vez que lo contaba, había más persas.','Cuando sopla el viento del mar, toda la llanura huele a la marisma.']);}
  for(const id in SIMPLE_GR){const I=G(id);if(I)buildSimple(I,SIMPLE_GR[id]);}
}
const GREECE_NPCS=[
{id:'agesilao',name:'Agesilao',title:'Rey de Esparta',glyph:'Α',look:{chiton:'#a8392b',himation:'#7a2a1e',beard:true,hair:'#8d8a85',beardC:'#9a968e',staff:true},
 cat:'Política',lesson:'Esparta y la paz del Rey',where:'En el Ágora de Esparta, junto al Pórtico Persa',
 summary:'Esparta tenía dos reyes a la vez, de dos familias (Agíadas y Euripóntidas), con mando militar y funciones religiosas; los controlaban cinco éforos elegidos cada año, un consejo de ancianos (gerusía) y la asamblea de ciudadanos. Agesilao II (c. 444-360), rey desde el 400, cojo de nacimiento, hizo la guerra en Asia y venció en Coronea (394). En el 386 Esparta impuso, con el apoyo del rey de Persia, la paz del Rey o de Antálcidas, que la convirtió en árbitro de Grecia.',
 intro:'Forastero. Soy Agesilao, hijo de Arquidamo. Uno de los dos reyes de los lacedemonios. Sí, el cojo. El oráculo advirtió de los peligros de un «reinado cojo», y aquí me tienes. Pregunta, pero que sea breve.',
 topics:[
  ['¿Qué es la paz del Rey?','El rey de Persia dicta: las ciudades griegas de Asia son suyas; las demás, libres y autónomas. Y nosotros, los lacedemonios, vigilamos que se cumpla. Así se acabó la guerra de Corinto. Los atenienses dicen que hemos vendido a los griegos de Asia al bárbaro. Yo digo que hemos disuelto las ligas de Tebas y de Argos, que nos amenazaban. Que cada cual juzgue.'],
  ['¿Cómo gobierna Esparta?','Somos dos reyes, de dos casas distintas, para que ninguno mande solo. En la guerra, uno manda el ejército. Pero cada mes juramos ante los cinco éforos gobernar según las leyes, y ellos juran mantenernos el trono mientras las cumplamos. Hay un consejo de veintiocho ancianos de más de sesenta años, y la asamblea de los iguales, que vota a gritos. Licurgo lo dispuso así.'],
  ['¿Es verdad que vives como los demás?','Como en las comidas comunes, como los demás, duermo donde los demás y llevo el mismo manto en invierno y en verano. Un rey debe ganarse a su pueblo con el ejemplo, no con el lujo. En Asia, los sátrapas persas se reían de mi aspecto. Después dejaron de reírse. Dice un amigo ateniense, Jenofonte, que algún día escribirá sobre mí. Espero que no exagere.']],
 quiz:{q:'¿Cuántos reyes tenía Esparta a la vez?',a:['Dos, de dos familias distintas','Uno, elegido de por vida','Cinco, los éforos'],ko:'No. Esparta tenía dos reyes a la vez, de las casas de los Agíadas y los Euripóntidas, controlados por cinco éforos.'}},
{id:'cinisca',name:'Cinisca',title:'Princesa espartana, vencedora olímpica',glyph:'Κ',look:{female:true,chiton:'#e9dfc8',himation:'#a8392b',hair:'#5b4532'},
 cat:'Sociedad',lesson:'Las mujeres espartanas',where:'En el Ágora de Esparta',
 summary:'Las espartanas tenían una libertad sorprendente para los demás griegos: hacían ejercicio al aire libre, se casaban más tarde, podían heredar y llegaron a poseer gran parte de las tierras. Cinisca, hermana del rey Agesilao, fue la primera mujer que ganó en los Juegos Olímpicos: sus caballos vencieron en la carrera de cuadrigas en el 396 y el 392, y una inscripción en Olimpia lo recuerda.',
 intro:'Salud, forastero. Soy Cinisca, hija del rey Arquidamo y hermana de Agesilao. ¿Has oído hablar de mí? Mis caballos han ganado dos veces la carrera de cuadrigas en Olimpia. La primera mujer de toda Grecia. Y no será la última.',
 topics:[
  ['¿Cómo ganó una mujer en Olimpia?','En las carreras de carros no gana el auriga, sino el dueño de los caballos. Las mujeres no podemos ni siquiera mirar los juegos, so pena de muerte. Pero mis caballos sí pueden correr. Mi hermano dice que lo hice para demostrar que la victoria en los carros no es mérito, sino dinero. Yo digo que lo hice porque mis caballos eran los mejores. He mandado poner en Olimpia una estatua con mi carro y una inscripción.'],
  ['¿Cómo viven las espartanas?','Corremos, luchamos y lanzamos el disco desde niñas, para tener hijos fuertes. Llevamos el peplo abierto por el costado, y los atenienses nos llaman «enseña-muslos». Nos casamos a los dieciocho o veinte, no a los catorce. Mandamos en la casa y en las tierras mientras los hombres están en la guerra o en las comidas comunes. Una mujer de Ática le preguntó a Gorgo, la esposa de Leónidas, por qué solo las espartanas mandan a sus maridos. «Porque solo nosotras parimos hombres», le dijo.'],
  ['¿Qué dicen las madres a sus hijos?','Cuando un hijo parte a la guerra, su madre le da el escudo y le dice: «Vuelve con él o sobre él». Con él, vencedor; sobre él, muerto, llevado en su escudo. Perderlo, para huir más deprisa, es la peor vergüenza. Los extranjeros lo cuentan como si fuéramos de piedra. Lloramos, como todas las madres. Pero en casa.']],
 quiz:{q:'¿Por qué fue famosa Cinisca?',a:['Fue la primera mujer en ganar en los Juegos Olímpicos, en la carrera de cuadrigas','Fue la primera mujer que gobernó Esparta','Ganó una guerra contra Atenas'],ko:'No. Cinisca, hermana de Agesilao, fue la primera mujer vencedora en Olimpia: sus caballos ganaron la carrera de cuadrigas en el 396 y el 392.'}},
{id:'hilota',name:'Sosias',title:'Hilota',glyph:'Σ',look:{exomis:true,chiton:'#8a7350',hair:'#3a2a1e',beard:true},
 cat:'Sociedad',lesson:'Los hilotas',where:'En los campos de Pitane, al noroeste de Esparta',
 summary:'Los hilotas eran los habitantes sometidos de Laconia y Mesenia: trabajaban las tierras de los espartanos y les entregaban la mitad de la cosecha. Eran muchos más que los ciudadanos, y los espartanos los temían: cada año los éforos les declaraban la guerra para poder matarlos sin culpa, y la krypteía, una prueba de los jóvenes, los vigilaba y asesinaba a los más peligrosos. Su sumisión permitía a los espartanos dedicarse solo a la guerra. Además había periecos, libres pero sin derechos políticos, que se dedicaban al comercio y la artesanía.',
 intro:'¿Qué miras? Nunca has visto a un hilota, ¿verdad? Me llamo Sosias. Esta tierra la trabajo yo, mi padre la trabajó, y la trabajarán mis hijos. Pero no es nuestra: es de un espartano que come en su sisitia con lo que yo cosecho. Habla bajo.',
 topics:[
  ['¿Qué es un hilota?','No somos esclavos de un amo, como los de Atenas: somos de la ciudad. Estamos atados a la tierra; no nos pueden vender fuera, pero tampoco podemos irnos. Entregamos la mitad de todo: cebada, vino, aceite, queso. Nuestros abuelos eran libres, en Laconia y en Mesenia, hasta que los espartanos los vencieron. Somos muchos más que ellos. Por eso nos temen.'],
  ['¿Cómo os tratan?','Cada año, al entrar en el cargo, los éforos nos declaran la guerra, para poder matarnos sin mancharse. A algunos nos emborrachan a la fuerza y nos llevan a las sisitias, para que los jóvenes vean lo vergonzosa que es la borrachera. Y por las noches salen los jóvenes de la krypteía, con un puñal, y matan a quien les parece. Cuentan que una vez prometieron la libertad a los dos mil hilotas que más se habían distinguido en la guerra. Desaparecieron todos.'],
  ['¿Y Mesenia?','Mesenia, al otro lado del Taigeto, es la tierra de nuestros padres. Hace ochenta años, después del gran terremoto, los mesenios se rebelaron y resistieron diez años en el monte Itome. Los atenienses mandaron ayuda a Esparta, y luego los espartanos los echaron, desconfiados. Algún día Mesenia será libre. Pero eso no lo digas aquí.']],
 quiz:{q:'¿Qué eran los hilotas?',a:['Habitantes sometidos que trabajaban las tierras de los espartanos y les entregaban parte de la cosecha','Los guerreros de élite del rey','Los sacerdotes de Ártemis'],ko:'No. Los hilotas eran la población sometida de Laconia y Mesenia, atada a la tierra, que entregaba la mitad de la cosecha a los espartanos.'}},
{id:'agoge',name:'Eudámidas',title:'Muchacho de la agogé',glyph:'Ε',look:{short:true,chiton:'#a8392b',hair:'#5b4532',scale:0.86},
 cat:'Sociedad',lesson:'La agogé, la educación espartana',where:'En el santuario de Artemis Ortia, junto al Eurotas',
 summary:'A los siete años los niños espartanos dejaban la casa e ingresaban en la agogé, la educación del Estado, organizados en grupos (agelai) bajo muchachos mayores y un magistrado, el paidonomos. Andaban descalzos, con un solo manto al año, dormían sobre cañas, comían poco y se les animaba a robar comida sin ser descubiertos. Aprendían a leer lo justo, a cantar, a bailar en coros y, sobre todo, a obedecer, aguantar y combatir. Las niñas también hacían ejercicio, aparte.',
 intro:'¿Eres extranjero? Se nota: hablas mucho. Soy Eudámidas, tengo doce años. Llevo cinco en la agogé. Mi grupo está ahí, practicando la danza de las armas. Yo he venido a por cañas del río para mi cama. Sin cuchillo, con las manos.',
 topics:[
  ['¿Cómo es tu vida?','Descalzo siempre, para tener los pies duros. Un solo manto para todo el año. Dormimos todos juntos, en camas de cañas del Eurotas. Comemos poco, para no engordar y crecer altos, y si tenemos hambre robamos: si te pillan, te azotan, no por robar, sino por dejarte pillar. Hay una historia de un chico que robó un zorro y lo escondió bajo el manto; antes de confesar dejó que el zorro le comiera el vientre.'],
  ['¿Aprendéis a leer?','Lo justo. Leer y escribir lo necesario, nada de discursos largos. Lo importante es hablar poco y bien. Cuando alguien nos amenaza, contestamos con pocas palabras. Un ateniense se burló de que nuestras espadas eran cortas, y un espartano le dijo: «Nos sirven para llegar hasta el enemigo». A eso lo llamáis hablar lacónico. Y cantamos mucho: los poemas de Tirteo, que animan a morir por la patria.'],
  ['¿Qué pasa en el altar de Ortia?','En la fiesta de la diosa ponen quesos en el altar. Nosotros tenemos que robarlos, y los mayores los defienden con látigos. Quien más aguanta sin quejarse, más honor gana. Yo saqué dos quesos el año pasado. Las cicatrices se ven en la espalda. Mi madre estaba orgullosa.']],
 quiz:{q:'¿A qué edad entraban los niños espartanos en la agogé?',a:['A los siete años','A los dieciocho','Nada más nacer'],ko:'No. A los siete años los niños dejaban su casa e ingresaban en la agogé, la educación organizada por el Estado.'}},
{id:'pastor',name:'Melanto',title:'Pastor de Micenas',glyph:'Μ',look:{exomis:true,chiton:'#8a7350',himation:'#5c4a32',hair:'#5b4532',beard:true,staff:true},
 cat:'Historia',lesson:'Micenas, la ciudad de Agamenón',where:'Junto a la aldea, al pie de la ciudadela de Micenas',
 summary:'Micenas fue el centro más poderoso de la Grecia de la Edad del Bronce (c. 1600-1100 a.C.), con un palacio, murallas ciclópeas, tumbas de cúpula y una escritura silábica, el lineal B. La civilización micénica se hundió hacia el 1200-1100 a.C. En época clásica Micenas era una pequeña ciudad que luchó en las Termópilas y Platea; en el 468 a.C. Argos la conquistó y deportó a sus habitantes. Los griegos la recordaban por Homero como la ciudad de Agamenón, «rica en oro».',
 intro:'Salud, viajero. Me llamo Melanto. Mis cabras pastan entre las piedras de la ciudad de Agamenón, «Micenas, rica en oro», dice Homero. Oro no queda. Los de Argos lo arrasaron todo hace ochenta años, cuando yo no había nacido. Si quieres, te enseño la puerta de los leones y la tumba de Atreo.',
 topics:[
  ['¿Quién construyó estas murallas?','Los Cíclopes, dicen todos: gigantes de un solo ojo que Preto trajo de Licia para Tirinto, y que luego trabajaron para Perseo aquí. Ningún hombre podría levantar estas piedras: algunas son más grandes que un buey. Los de Argos intentaron derribarlas y apenas pudieron. Por eso a las murallas así las llaman ciclópeas.'],
  ['Cuéntame la historia de los Atridas','Atreo y Tiestes eran hermanos y se disputaban el trono. Atreo mató a los hijos de Tiestes y se los sirvió en un banquete. Desde entonces, la casa está maldita. Su hijo Agamenón sacrificó a su hija Ifigenia para que soplaran los vientos hacia Troya; al volver, diez años después, su esposa Clitemnestra lo mató en el baño. Y Orestes, su hijo, mató a su madre. Lo habrás visto en el teatro de Atenas: Esquilo, Sófocles, Eurípides.'],
  ['¿Qué pasó con la ciudad?','Micenas era pequeña, pero orgullosa: mandó ochenta hombres a las Termópilas con Leónidas y luchó en Platea, mientras Argos no quiso luchar contra los persas. Los argivos no se lo perdonaron. Hace ochenta y dos años la sitiaron, la tomaron y se llevaron a todos: unos a Macedonia, otros a Cleonas. Desde entonces aquí solo quedamos unos pocos pastores y los fantasmas.']],
 quiz:{q:'¿Por qué se llaman «ciclópeas» las murallas de Micenas?',a:['Porque, según la leyenda, las construyeron los Cíclopes, de tan grandes que son sus piedras','Porque tienen forma circular','Porque las construyó un rey llamado Cíclope'],ko:'No. Los griegos creían que solo los Cíclopes, gigantes míticos, podían haber movido esas piedras enormes.'}},
{id:'calitea',name:'Calitea',title:'Sacerdotisa de Hera',glyph:'Κ',look:{female:true,chiton:'#f4efe4',himation:'#c9a24a',veil:'#f4efe4',hair:'#3b2a1e'},
 cat:'Religión',lesson:'El Hereo y el culto de Hera',where:'Ante el Hereo de Argos, al sur de Micenas',
 summary:'Hera, esposa de Zeus, diosa del matrimonio, era la gran diosa de la Argólide. Su santuario entre Argos y Micenas tenía un templo arcaico que ardió en el 423 por un descuido de la sacerdotisa Criseida; el nuevo, de Eupólemo, albergaba la Hera de oro y marfil de Policleto. Los argivos contaban los años por los años de servicio de las sacerdotisas de Hera, como los atenienses por sus arcontes.',
 intro:'Bienvenido al santuario de Hera, extranjero. Soy Calitea, sacerdotisa de la diosa. Por mis años de servicio cuentan el tiempo los argivos: este es el año octavo de Calitea. Entra a ver a la diosa, la que hizo Policleto. Pero no acerques la lámpara al velo: ya ardió aquí un templo.',
 topics:[
  ['¿Qué pasó con el templo antiguo?','Hace treinta y siete años, la sacerdotisa Criseida se quedó dormida con una lámpara encendida junto a las guirnaldas sagradas. El fuego lo devoró todo. Ella huyó a Tegea, de vergüenza y de miedo, y los argivos eligieron otra sacerdotisa. Tucídides lo cuenta en su historia. Luego construyeron este templo nuevo, más abajo en la colina.'],
  ['¿Cómo es la estatua de Policleto?','La diosa está sentada en un trono, de oro y marfil, enorme. Lleva una corona con las Horas y las Gracias, en una mano una granada y en la otra un cetro con un cuco: Zeus se convirtió en cuco para acercarse a ella cuando era doncella. Policleto, el de las proporciones perfectas, la hizo ya viejo. Es tan bella como el Zeus de Fidias en Olimpia, dicen los argivos. Los atenienses, claro, no están de acuerdo.'],
  ['¿Es verdad lo de Cleobis y Bitón?','Era una sacerdotisa de Hera, madre de dos jóvenes de Argos. Para llegar a la fiesta, como los bueyes no llegaban del campo, sus hijos se uncieron al carro y la llevaron hasta aquí, cuarenta y cinco estadios. Ella pidió a la diosa para ellos el mejor don. Se durmieron en el templo y no despertaron. Solón se lo contó a Creso: morir en la gloria es la mayor felicidad. En Delfos tienen sus estatuas.']],
 quiz:{q:'¿Quién hizo la estatua de oro y marfil de Hera en el Hereo de Argos?',a:['Policleto','Fidias','Praxíteles'],ko:'No. La gran estatua de oro y marfil de Hera era obra de Policleto, el escultor de Argos.'}}
];
